<?php
namespace Delnavazan\Platform\Admin\Controller;
use Delnavazan\Platform\Core\Application\{TeachingEligibilityService,InstrumentIntroCourseDefaultService,TeacherAcceptingStateService};
use Delnavazan\Platform\Core\Infrastructure\Repository\TeachingEligibilityRepository;

/** Narrow administrator-only management surface; it deliberately has no public route. */
final class TeachingEligibilityController {
    public static function handlePost():void{if(($_SERVER['REQUEST_METHOD']??'')!=='POST')return;if(!current_user_can('dzn_manage_teaching_eligibility'))wp_die('Access denied.','Delnavazan',['response'=>403]);$post=wp_unslash($_POST);$action=sanitize_key($post['dzn_action']??'');if(!in_array($action,['set_teacher_course_eligibility','set_instrument_intro_default','set_teacher_accepting_state'],true))return;check_admin_referer('dzn_platform_'.$action);try{match($action){'set_teacher_course_eligibility'=>(new TeachingEligibilityService())->setEligibility($post),'set_instrument_intro_default'=>(new InstrumentIntroCourseDefaultService())->set($post),'set_teacher_accepting_state'=>(new TeacherAcceptingStateService())->set($post)};self::redirect('Saved. The teaching record has been updated.');}catch(\Throwable){self::redirect('Operation failed; no change was saved.',true);}}
    public static function screen():void{if(!current_user_can('dzn_manage_teaching_eligibility')){echo '<div class="wrap"><p>Access denied.</p></div>';return;}$repo=new TeachingEligibilityRepository();echo '<div class="wrap"><h1>Teaching eligibility</h1><p>These Core facts are authoritative. They do not use Amelia, Hamnavaz, profile text, or contact matching.</p>';self::messages();self::form('set_teacher_course_eligibility','Teacher/Course eligibility',[['teacher_id','Teacher'],['course_id','Course'],['status','Status: active or inactive'],['effective_from','Effective UTC (YYYY-MM-DD HH:MM:SS)'],['effective_until','Effective UTC until (optional)'],['reason_code','Reason code']]);self::table('Teacher/Course eligibility',$repo->rows('teacher_course_eligibilities'));self::form('set_instrument_intro_default','Instrument default Intro Course',[['instrument_id','Instrument'],['course_id','Intro Course'],['status','Status: active or inactive'],['reason_code','Reason code']]);self::table('Instrument defaults',$repo->rows('instrument_intro_course_defaults'));self::form('set_teacher_accepting_state','Teacher accepting state',[['teacher_id','Teacher'],['state','State: accepting, limited, or paused'],['reason_code','Reason code']]);self::table('Teacher accepting states',$repo->rows('teacher_accepting_states'));echo '</div>';}
    private static function form(string $action,string $title,array $fields):void{$context=['teacher_id'=>self::contextId('teacher_id'),'course_id'=>self::contextId('course_id')];echo '<h2>'.esc_html($title).'</h2><form method="post">';wp_nonce_field('dzn_platform_'.$action);echo '<input type="hidden" name="dzn_action" value="'.esc_attr($action).'">';foreach($fields as[$name,$label]){if($name==='teacher_id'){self::teacherSelector($context[$name]);continue;}if($name==='course_id'){self::courseSelector($label,$context[$name]);continue;}if($name==='instrument_id'){self::instrumentSelector();continue;}$value='';echo '<p><label>'.esc_html($label).'<br><input class="regular-text" name="'.esc_attr($name).'" value="'.esc_attr($value).'"></label></p>';}submit_button('Save');echo '</form>';}
    private static function teacherSelector(string $selected):void{$options=(new \Delnavazan\Platform\Core\Application\CoreReadService())->teacherOptionsForTeachingEligibility();echo '<p><label>Teacher<br><select required name="teacher_id"><option value="">Choose a teacher</option>';foreach($options as$row){$label=(string)($row->display_name?:$row->english_name?:$row->persian_name?:'Teacher');if($row->status!=='active')$label.=' (inactive)';echo '<option value="'.esc_attr((string)$row->id).'"'.selected($selected,(string)$row->id,false).'>'.esc_html($label).'</option>';}echo '</select></label></p>';}
    private static function courseSelector(string $label,string $selected):void{$options=(new \Delnavazan\Platform\Core\Application\CoreReadService())->courseOptionsForTeachingEligibility();$introOnly=str_contains(strtolower($label),'intro');echo '<p><label>'.esc_html($label).'<br><select required name="course_id"><option value="">Choose a Course</option>';foreach($options as$row){if($introOnly&&$row->course_type!=='introductory')continue;$name=(string)($row->name_en?:$row->name_fa?:'Course');$instrument=(string)($row->instrument_en?:$row->instrument_fa?:'');$text=$instrument!==''?$name.' · '.$instrument:$name;if($row->status!=='active')$text.=' (inactive)';echo '<option value="'.esc_attr((string)$row->id).'"'.selected($selected,(string)$row->id,false).'>'.esc_html($text).'</option>';}echo '</select></label></p>';}
    private static function instrumentSelector():void{$options=(new \Delnavazan\Platform\Core\Application\CoreReadService())->instrumentOptionsForTeachingEligibility();echo '<p><label>Instrument<br><select required name="instrument_id"><option value="">Choose an instrument</option>';foreach($options as$row){$label=(string)($row->name_en?:$row->name_fa?:'Instrument');if($row->status!=='active')$label.=' (inactive)';echo '<option value="'.esc_attr((string)$row->id).'">'.esc_html($label).'</option>';}echo '</select></label></p>';}
    private static function contextId(string $key):string{$value=wp_unslash($_GET[$key]??'');return is_scalar($value)&&preg_match('/^[1-9][0-9]*$/D',(string)$value)?(string)absint($value):'';}
    private static function table(string $title,array $rows):void{echo '<h3>'.esc_html($title).'</h3>';if(!$rows){echo '<p>No records.</p>';return;}$fields=array_keys(get_object_vars($rows[0]));echo '<table class="widefat striped"><thead><tr>';foreach($fields as$f)echo '<th>'.esc_html($f).'</th>';echo '</tr></thead><tbody>';foreach($rows as$row){echo '<tr>';foreach($fields as$f)echo '<td>'.esc_html((string)($row->$f??'')).'</td>';echo '</tr>';}echo '</tbody></table>';}
    private static function messages():void{if(!isset($_GET['dzn_notice']))return;echo '<div class="notice '.esc_attr((($_GET['dzn_error']??'')==='1')?'notice-error':'notice-success').'">'.esc_html(sanitize_text_field(wp_unslash($_GET['dzn_notice']))).'</div>';}
    private static function redirect(string $notice,bool $error=false):never{$url=add_query_arg(['page'=>'dzn-teaching-eligibility','dzn_notice'=>$notice,'dzn_error'=>$error?'1':'0'],admin_url('admin.php'));nocache_headers();if(wp_safe_redirect($url))exit;wp_die(esc_html($notice),'Delnavazan',['response'=>$error?500:200]);}
}
